import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def reports(ctx):
    inputs = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor([1, 2 + int(ctx.index) % 2])
    return {"inputs": synth.Tensor(inputs), "targets": synth.Tensor(targets), "report_mask": synth.Tensor(torch.tensor([1, 1])), "diagnostic_token_ids": synth.Tensor(torch.tensor([[0, 1], [3, 0]])), "diagnostic_token_mask": synth.Tensor(torch.tensor([[1, 1], [1, 0]])), "diagnostic_concept_mask": synth.Tensor(torch.tensor([1, 1])), "diagnostic_positive_mask": synth.Tensor(torch.tensor([1, 0])), "diagnostic_concept_weights": synth.Tensor(torch.ones(2)), "sample_weights": synth.Tensor(torch.tensor(1.0))}
dataset = synth.Spec("diagnostic-reports", generator=reports, size=8, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class SequencePredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=8)
    def forward(self, inputs):
        return {"logits": self.network(inputs).reshape(-1, 2, 4)}
trainer = Trainer(SequencePredictor(), train, recipe="structured-objective", recipe_config={"loss": "diagnostic-loss", "loss_kwargs": {"lambda_pos": 0.001, "lambda_neg": 0.00025, "tau": 8.0}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}, "report_mask": {"batch": "report_mask"}, "diagnostic_token_ids": {"batch": "diagnostic_token_ids"}, "diagnostic_token_mask": {"batch": "diagnostic_token_mask"}, "diagnostic_concept_mask": {"batch": "diagnostic_concept_mask"}, "diagnostic_positive_mask": {"batch": "diagnostic_positive_mask"}, "diagnostic_concept_weights": {"batch": "diagnostic_concept_weights"}, "sample_weights": {"batch": "sample_weights"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
